function passphraseIssue(value, confirmation) {
  if ([...value].length < 8) return "口令至少需要 8 个字符";
  if (new TextEncoder().encode(value).length > 1024) return "口令不能超过 1024 UTF-8 字节";
  if (confirmation !== void 0 && value !== confirmation) return "两次输入的口令不一致";
  return null;
}
