const __vite_glob_0_20 = "-- Host-observed business identities for the activity view. These are metadata,\n-- never credentials, permissions, executable arguments or user authorizations.\nCREATE TABLE IF NOT EXISTS application_activity_subjects (\n operation_id TEXT NOT NULL REFERENCES application_data_operations(operation_id) ON DELETE CASCADE,\n kind TEXT NOT NULL CHECK(kind IN ('connection','mail-send','mail-draft')),\n subject_id TEXT NOT NULL,\n PRIMARY KEY(operation_id,kind,subject_id)\n);\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS application_activity_subjects_lookup ON application_activity_subjects(kind,subject_id,operation_id);\n--> statement-breakpoint\n-- Only the original preparation operation has a provable old link. Do not infer\n-- later executes or reads from their arguments, timestamps, or current bindings.\nINSERT OR IGNORE INTO application_activity_subjects(operation_id,kind,subject_id)\n SELECT s.operation_id,'mail-send',s.id FROM mail_send_intents s\n JOIN application_data_operations o ON o.operation_id=s.operation_id AND o.project_id=s.project_id AND o.app_id='mail';\n\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS application_data_operations_activity_time ON application_data_operations(started_at,operation_id);\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS application_invocations_activity_time ON application_invocations(started_at,operation_id);\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS mail_send_intents_activity_time ON mail_send_intents(created_at,id);\n";
const __vite_glob_0_21 = "-- Host observations only. Never credentials, arbitrary argv/configs, model claims,\n-- user messages, or a replacement for application/send execution records.\nCREATE TABLE IF NOT EXISTS capability_run_preparations (\n run_id TEXT PRIMARY KEY NOT NULL REFERENCES capability_runs(run_id),\n evidence_json TEXT NOT NULL,\n evidence_hash TEXT NOT NULL,\n prepared_at TEXT NOT NULL\n);\n--> statement-breakpoint\nCREATE TABLE IF NOT EXISTS capability_bridge_observations (\n run_id TEXT NOT NULL REFERENCES capability_runs(run_id),\n bridge_id TEXT NOT NULL REFERENCES capability_run_processes(process_id),\n evidence_json TEXT NOT NULL,\n evidence_hash TEXT NOT NULL,\n observed_at TEXT NOT NULL,\n PRIMARY KEY(run_id,bridge_id)\n);\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS capability_run_evidence_time ON capability_run_preparations(prepared_at,run_id);\n";
const __vite_glob_0_22 = "-- Preserve original M4 metadata before any schema2 migration or task pointer change.\n-- These records and capability_session_refs survive deletion of the UI task/project.\n-- prepared means verified source retention only, never native discovery or execution.\nCREATE TABLE IF NOT EXISTS capability_legacy_migration_preparations (\n task_id TEXT PRIMARY KEY NOT NULL REFERENCES capability_session_snapshots(task_id),\n source_snapshot_json TEXT NOT NULL,\n source_record_json TEXT NOT NULL,\n source_snapshot_hash TEXT NOT NULL,\n source_identity_json TEXT NOT NULL,\n bound_native_session_id TEXT,\n evidence_json TEXT,\n evidence_hash TEXT,\n manifest_json TEXT,\n manifest_hash TEXT,\n state TEXT NOT NULL CHECK(state IN ('held','prepared','migrated')),\n issue_code TEXT,\n created_at TEXT NOT NULL,\n updated_at TEXT NOT NULL,\n CHECK((evidence_json IS NULL AND evidence_hash IS NULL AND manifest_json IS NULL AND manifest_hash IS NULL)\n    OR (evidence_json IS NOT NULL AND evidence_hash IS NOT NULL AND manifest_json IS NOT NULL AND manifest_hash IS NOT NULL))\n);\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS capability_legacy_preparation_state ON capability_legacy_migration_preparations(state,task_id);\n";
